ValidationRule.errorConditionFormula:
AND(
ISCHANGED(Status__c),
OR(
($Profile.Name = 'TAM Admin' &&
NOT(
OR(
RecordType.Name = 'ESO Support Request',
RecordType.Name = 'Vertical CIO/Strategist Request'
)
)
),
($Profile.Name = 'TAM' &&
(AND(
NOT($Permission.Unified_Endpoint_Security_Support_Request_Edit)

) &&
OR(
RecordType.Name = 'Training Request',
RecordType.Name = 'Unified Endpoint Security Support Request'
)
) &&
NOT(
OR(
RecordType.Name = 'ESO Support Request',
RecordType.Name = 'Vertical CIO/Strategist Request'
)
)
)
)
)
